using VisionFramework;
namespace VisionEditor.Core;
public sealed partial class GraphEditorDocument {
 SolutionDocument PropagateGroupInterface(SolutionDocument document,ProcedureDocument changed){
  var procedures=document.Procedures.ToDictionary(p=>p.Id,StringComparer.Ordinal);
  void Apply(ProcedureDocument body){var before=procedures[body.Id];procedures[body.Id]=body;if(body.GroupOwner is not {} owner)return;var parent=procedures[owner.ProcedureId];var signature=WorkflowCalls.From(body);var oldSignature=WorkflowCalls.From(before);var inputMapping=oldSignature.Inputs.ToDictionary(p=>p.Name,p=>signature.Inputs.SingleOrDefault(n=>n.Id==p.Id),StringComparer.Ordinal);var oldPorts=oldSignature.Outputs;var mapping=oldPorts.ToDictionary(p=>p.Name,p=>signature.Outputs.SingleOrDefault(n=>n.Id==p.Id),StringComparer.Ordinal);
   WorkflowValueReference? Reference(WorkflowValueReference source)=>source.Kind==WorkflowSourceKind.NodeOutput&&source.Id==owner.NodeId&&source.Port is {} port&&mapping.TryGetValue(port,out var updated)?updated is null?null:source with{Port=updated.Name}:source;
   WorkflowInterfaceItem Interface(WorkflowInterfaceItem item){if(item.NodeId!=owner.NodeId||item.Port is null||!mapping.TryGetValue(item.Port,out var updated))return item;return updated is null?item with{NodeId=null,Port=null}:item with{Port=updated.Name,Kind=updated.Kind,Cardinality=updated.Cardinality};}
   GroupBreakBindings? Bindings(GroupBreakBindings? bindings,bool inside){GroupOperand? Operand(GroupOperand? operand){if(operand is null||operand.Inside!=inside||operand.Source is null)return operand;var source=Reference(operand.Source);return source is null?null:operand with{Source=source};}return bindings is null?null:new(Operand(bindings.Left),Operand(bindings.Right));}
   var configuration=parent.Configuration with{Subscriptions=parent.Configuration.Subscriptions.Where(b=>Reference(b.Source)is not null&&!(b.NodeId==owner.NodeId&&!b.IsParameter&&inputMapping.TryGetValue(b.Target,out var input)&&input is null)).Select(b=>b with{Source=Reference(b.Source)!,Target=b.NodeId==owner.NodeId&&!b.IsParameter&&inputMapping.TryGetValue(b.Target,out var input)&&input is not null?input.Name:b.Target}).ToArray(),Inputs=parent.Configuration.Inputs.Select(Interface).ToArray(),Outputs=parent.Configuration.Outputs.Select(Interface).ToArray(),Displays=parent.Configuration.Displays.Select(Interface).ToArray(),Variables=parent.Configuration.Variables.Select(v=>v.SourceNode==owner.NodeId&&v.SourcePort is {} port&&mapping.TryGetValue(port,out var updated)?v with{SourceNode=updated is null?null:v.SourceNode,SourcePort=updated?.Name}:v).ToArray()};
   var nodes=parent.Nodes.Select(n=>n with{Call=n.Id==owner.NodeId?signature:n.Call,GroupBreak=Bindings(n.GroupBreak,false)}).ToArray();var edges=parent.Connections.Where(e=>e.FromNode!=owner.NodeId||!mapping.TryGetValue(e.FromPort,out var target)||target is not null).Select(e=>e.FromNode==owner.NodeId&&mapping.TryGetValue(e.FromPort,out var target)&&target is not null?e with{FromPort=target.Name}:e).ToArray();
   if(parent.GroupOwner is {} outer){var grand=procedures[outer.ProcedureId];procedures[grand.Id]=grand with{Nodes=grand.Nodes.Select(n=>n.Id==outer.NodeId?n with{GroupBreak=Bindings(n.GroupBreak,true)}:n).ToArray()};}
   Apply(parent with{Nodes=nodes,Connections=edges.Where(e=>e.ToNode!=owner.NodeId||!inputMapping.TryGetValue(e.ToPort,out var input)||input is not null).Select(e=>e.ToNode==owner.NodeId&&inputMapping.TryGetValue(e.ToPort,out var input)&&input is not null?e with{ToPort=input.Name}:e).ToArray(),Configuration=configuration});
  }
  Apply(changed);var result=document with{Procedures=document.Procedures.Select(p=>procedures[p.Id]).ToArray()};
  foreach(var next in result.Procedures){var old=document.Procedures.Single(p=>p.Id==next.Id);var oldIssues=GraphValidator.Validate(old,registry).Issues.Select(i=>(i.Code,i.NodeId,i.Message)).ToHashSet();var problem=GraphValidator.Validate(next,registry).Issues.FirstOrDefault(i=>i.Code is "PortType" or "WorkflowConfiguration" or "GroupBreakType" or "GroupBreakSource"&&!oldIssues.Contains((i.Code,i.NodeId,i.Message)));if(problem is not null)throw new InvalidOperationException("接口变更与现有订阅不兼容，请先调整下游绑定："+problem.Message);}
  return result;
 }
}
